#include "gateway/credential_store.hpp"
#include "manager/credential_store.hpp"
#include "manager/validation.hpp"
#include <iostream>
#include <string>
int main(){const std::string service="CloudLLM-Manager-Interop-Test",username="openrouter|default";const std::wstring secret=L"MANAGER_TEST_SECRET";auto manager_store=manager::make_credential_store();manager_store->remove(service,username);if(manager_store->store(service,username,{secret.data(),secret.size()})!=manager::StoreResult::success){std::cerr<<"Manager store failed\n";return 1;}auto cleanup=[&]{manager_store->remove(service,username);};auto gateway_store=gateway::make_platform_credential_store();auto read=gateway_store->get(service,username);auto items=manager_store->list(service);bool listed=false;for(const auto& item:items)listed=listed||item.username==username;if(!read||read->view()!="MANAGER_TEST_SECRET"||!listed){cleanup();std::cerr<<"Manager-to-Gateway interop failed\n";return 2;}if(manager_store->remove(service,username)!=manager::StoreResult::success){std::cerr<<"Manager remove failed\n";return 3;}if(gateway_store->get(service,username)){std::cerr<<"Credential remained after delete\n";return 4;}std::string reason;if(!manager::valid_service_name("CloudLLM",reason)||!manager::valid_username("openrouter|default",reason)){std::cerr<<"Validation failed\n";return 5;}std::cout<<"Credential Manager-to-Gateway interoperability passed\n";return 0;}
